ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| UserName!=/\$$/
| ImageFileName=/(vssadmin|wmic|bcdedit|wbadmin|net1?|taskkill)\.exe$/i
| regex("(delete\\s+shadows|resize\\s+shadowstorage|shadowcopy.*delete|recoveryenabled\\s+no|bootstatuspolicy\\s+ignoreallfailures|delete\\s+catalog|delete\\s+systemstatebackup|stop.*(veeam|sql|backup|sophos|acronis|mcafee)|taskkill.*(veeam|sql|backup|sophos))", field=CommandLine, flags="i")
| InhibitAction := case {
    ImageFileName=/vssadmin\.exe$/i | "vss_delete";
    ImageFileName=/wmic\.exe$/i | "wmi_shadow_delete";
    ImageFileName=/bcdedit\.exe$/i | "bcdedit_recovery_off";
    ImageFileName=/wbadmin\.exe$/i | "wbadmin_catalog_delete";
    ImageFileName=/(net1?|taskkill)\.exe$/i | "service_kill";
    * | "other"
  }
| groupBy([aid, ComputerName, UserName], function=[count(field=InhibitAction, distinct=true, as=DistinctActions), collect([InhibitAction, CommandLine, ImageFileName])])
| DistinctActions >= 2
